PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,demo INTEGER NOT NULL DEFAULT 1,ai_budget INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT REFERENCES users(id),workspace_id TEXT REFERENCES workspaces(id),role TEXT NOT NULL CHECK(role IN ('owner','manager','staff')),PRIMARY KEY(user_id,workspace_id));
CREATE TABLE IF NOT EXISTS sites(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL,theme TEXT NOT NULL,business TEXT NOT NULL,draft TEXT NOT NULL,draft_version INTEGER NOT NULL DEFAULT 1,published_id TEXT,domain TEXT,domain_state TEXT NOT NULL DEFAULT 'unconfigured',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(id),document TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS catalog(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),site_id TEXT NOT NULL REFERENCES sites(id),kind TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),image TEXT NOT NULL,category TEXT NOT NULL,duration INTEGER,private_notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS variants(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES catalog(id),name TEXT NOT NULL,stock INTEGER NOT NULL CHECK(stock>=0));
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,contact TEXT NOT NULL,channel TEXT NOT NULL,channel_id TEXT,UNIQUE(workspace_id,channel,channel_id));
CREATE TABLE IF NOT EXISTS inquiries(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),site_id TEXT NOT NULL REFERENCES sites(id),customer_id TEXT NOT NULL REFERENCES customers(id),data TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',demo INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),site_id TEXT NOT NULL REFERENCES sites(id),customer_id TEXT NOT NULL REFERENCES customers(id),status TEXT NOT NULL CHECK(status IN ('awaiting_payment','paid_test','cancelled','expired','fulfilled_test')),total INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'MNT',idempotency_key TEXT NOT NULL,fingerprint TEXT NOT NULL,access_hash TEXT NOT NULL,expires INTEGER NOT NULL,demo INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),variant_id TEXT NOT NULL REFERENCES variants(id),name TEXT NOT NULL,variant_name TEXT NOT NULL,unit_price INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS payment_attempts(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),provider TEXT NOT NULL,status TEXT NOT NULL,provider_reference TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),site_id TEXT NOT NULL REFERENCES sites(id),service_id TEXT NOT NULL REFERENCES catalog(id),customer_id TEXT NOT NULL REFERENCES customers(id),starts INTEGER NOT NULL,ends INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'reserved_test',demo INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS prevent_booking_overlap BEFORE INSERT ON bookings WHEN NEW.status='reserved_test' AND EXISTS(SELECT 1 FROM bookings WHERE site_id=NEW.site_id AND status='reserved_test' AND starts<NEW.ends AND ends>NEW.starts) BEGIN SELECT RAISE(ABORT,'booking_conflict'); END;
CREATE TABLE IF NOT EXISTS integrations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider TEXT NOT NULL,state TEXT NOT NULL,asset_id TEXT,UNIQUE(workspace_id,provider));
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),event_id TEXT NOT NULL,UNIQUE(workspace_id,event_id));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),channel_id TEXT NOT NULL,sender TEXT NOT NULL,body TEXT NOT NULL,direction TEXT NOT NULL,state TEXT NOT NULL,demo INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS social_drafts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),site_id TEXT NOT NULL REFERENCES sites(id),record_id TEXT NOT NULL REFERENCES catalog(id),caption TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft',external_id TEXT,offer_site_id TEXT REFERENCES sites(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),draft_id TEXT NOT NULL REFERENCES social_drafts(id),state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,error TEXT,UNIQUE(draft_id));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),actor_id TEXT,action TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS usage(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),capability TEXT NOT NULL,units INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),mime TEXT NOT NULL,bytes BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
